export function getExerciseSvgHtml(keyOrFilename: string | undefined): string {
  if (!keyOrFilename) return '';
  
  // 0. If it's a data URI for raster image (JPEG, PNG, WebP) or an asset image path, render an img tag
  if (keyOrFilename.startsWith('data:image/jpeg') || keyOrFilename.startsWith('data:image/png') || keyOrFilename.startsWith('data:image/webp') || keyOrFilename.startsWith('assets/')) {
    return `<img src="${keyOrFilename}" class="pose-vector-graphic" style="width:100%;height:auto;max-height:280px;object-fit:contain;display:block;border-radius:12px;background:#090d16;" alt="Anatomical Exercise Guide" />`;
  }

  // 0.1 If it's a data:image/svg+xml;base64,... decode directly
  if (keyOrFilename.startsWith('data:image/svg+xml;base64,')) {
    try {
      const base64Data = keyOrFilename.replace('data:image/svg+xml;base64,', '');
      return atob(base64Data);
    } catch {
      // Fallback
    }
  }

  // 0.2 If it's already raw SVG XML markup
  if (keyOrFilename.trim().startsWith('<svg')) {
    return keyOrFilename;
  }
  
  // 1. Direct filename match
  const filename = keyOrFilename.split('/').pop() || '';
  if (EXERCISE_RAW_SVGS[filename]) {
    return EXERCISE_RAW_SVGS[filename];
  }
  
  // 2. Keyword matching
  const k = keyOrFilename.toLowerCase();
  if (k.includes('squat') || k.includes('hack') || k.includes('rack')) {
    return EXERCISE_RAW_SVGS['squat_rack_squats.svg'] || '';
  }
  if (k.includes('shoulder') || k.includes('overhead') || k.includes('lateral')) {
    return EXERCISE_RAW_SVGS['shoulder_press_machine.svg'] || '';
  }
  if (k.includes('lat') || k.includes('pull') || k.includes('row')) {
    return EXERCISE_RAW_SVGS['lat_pulldown_machine.svg'] || '';
  }
  if (k.includes('bench') || k.includes('chest') || k.includes('incline') || k.includes('fly') || k.includes('pec')) {
    return EXERCISE_RAW_SVGS['bench_press_flat.svg'] || '';
  }
  if (k.includes('leg_press') || k.includes('leg') || k.includes('calf') || k.includes('extension') || k.includes('curl') || k.includes('abductor')) {
    return EXERCISE_RAW_SVGS['leg_press_machine.svg'] || '';
  }
  if (k.includes('bicep') || k.includes('preacher') || k.includes('arm')) {
    return EXERCISE_RAW_SVGS['bicep_curl_preacher.svg'] || '';
  }
  if (k.includes('kettlebell') || k.includes('dumbbell') || k.includes('swing') || k.includes('thrust') || k.includes('hyperextension')) {
    return EXERCISE_RAW_SVGS['kettlebell_swings.svg'] || '';
  }
  if (k.includes('cable') || k.includes('tricep') || k.includes('dip') || k.includes('pulley')) {
    return EXERCISE_RAW_SVGS['cable_tricep_pushdown.svg'] || '';
  }

  // Fallback
  return EXERCISE_RAW_SVGS['squat_rack_squats.svg'] || '';
}
